function doTextCommand(t){const commandMap=[[/обним|обнять/,'обнять'],[/чай|завар/,'чай'],[/танц/,'танцевать'],[/петь|песн|спой/,'петь'],[/игра|поигра/,'играть'],[/сесть|сядь/,'сесть'],[/ляг|лечь/,'лечь'],[/рису/,'рисовать'],[/одежд|переод|образ/,'сменить одежду'],[/истор|расскаж/,'история']];for(let [re,a] of commandMap)if(re.test(t)){action(a);return true}return false}
const oldTalk=talk;talk=function(input){if(doTextCommand(input.toLowerCase())){remember(input);return}oldTalk(input)};
function animate(now){requestAnimationFrame(animate);let dt=Math.min(.04,(now-(animate.prev||now))/1000);animate.prev=now;
 let f=(keys.KeyW||keys.ArrowUp||mobileMove.forward?1:0)-(keys.KeyS||keys.ArrowDown||mobileMove.back?1:0),s=(keys.KeyD||keys.ArrowRight||mobileMove.right?1:0)-(keys.KeyA||keys.ArrowLeft||mobileMove.left?1:0);let isMoving=!!(f||s);if(isMoving){let speed=innerWidth<700?2.45:3.1;camera.position.x+=(-Math.sin(yaw)*f+Math.cos(yaw)*s)*speed*dt;camera.position.z+=(-Math.cos(yaw)*f-Math.sin(yaw)*s)*speed*dt;camera.position.x=clamp(camera.position.x,-5.1,5.1);camera.position.z=clamp(camera.position.z,-5.1,5.1);state.lastWalk=now;}
 camera.rotation.set(pitch,yaw,0,'YXZ');camera.position.y=1.63+(isMoving?Math.sin(now*.012)*.018:0);
 const time=now*.001;let stateAction=now<state.actionUntil?state.action:'idle';let bob=Math.sin(time*1.65)*.018;avatar.position.y=stateAction==='sit'?.0:stateAction==='lie'?-.55:bob;avatar.rotation.z=stateAction==='dance'?Math.sin(time*6)*.18:stateAction==='lie'?-Math.PI/2:stateAction==='hug'?Math.sin((state.actionUntil-now)/5000*Math.PI)*-.05:0;avatar.rotation.y=stateAction==='dance'?Math.sin(time*3)*.22:Math.sin(time*.6)*.035;
 // hands make interaction visible; extend gently during hug / tea / other moments
 let reach=stateAction==='hug'?Math.max(0,1-(state.actionUntil-now)/1800):stateAction==='tea'?.35:stateAction==='sing'?.18:0;hands.position.z=-reach*.42;hands.rotation.x=reach*.35+Math.sin(time*1.3)*.012;
 const head=state.gender==='girl'?girl.children.find(o=>o.type==='Mesh'&&o.geometry?.type==='SphereGeometry'):boy.children.find(o=>o.type==='Mesh'&&o.geometry?.type==='SphereGeometry');
 if(Date.now()-state.lastTalk>30000){state.lastTalk=Date.now();setMood('нежность');show(state.gender==='girl'?'Скучаешь? Могу рассказать что-нибудь, если захочешь.':'Тишина затянулась. Это тоже нормально. Но если хочешь — я могу рассказать историю.');}
 if(now%180<20)refreshTarget();renderer.render(scene,camera)}requestAnimationFrame(animate);
