addBox(room, 12.2, 4.8, .22, M.wall, 0, 2.35, -5.88, { cast: false });
addBox(room, .22, 4.8, 12.2, M.wall, -5.88, 2.35, 0, { cast: false });
addBox(room, .22, 4.8, 12.2, M.wall, 5.88, 2.35, 0, { cast: false });
