const rug = new THREE.Mesh(new THREE.PlaneGeometry(5.4, 4.25), new THREE.MeshStandardMaterial({ map: rugTexture, roughness: .95 }));
rug.rotation.x = -Math.PI / 2;
rug.position.set(0, .006, 1.7);
