      : ' И имя скажи. А то так и буду звать тебя «эй» — а это не по-дружески.';
  } else if (pastMemory && Math.random() < .3) {
    reply += isGirl
      ? ` Ты раньше сказал(а): «${quoteSnippet(pastMemory.text, 54)}». Сейчас это звучит иначе — или мне только кажется.`
