function updateLoading(progress, gender) {
  const p = clamp(progress, 0, 1);
  els.loadBar.style.width = Math.max(8, Math.round(p * 100)) + '%';
  if (loadedCount >= 2) els.loadStatus.textContent = 'комната дышит';
  else if (loadedCount >= 1) els.loadStatus.textContent = 'ещё один голос в комнате…';
  else if (gender === 'girl') els.loadStatus.textContent = 'загружаю Миру…';
  else els.loadStatus.textContent = 'загружаю Льва…';
}
function markReady(gender) {
  const button = startButtons.find(button => button.dataset.start === gender);
  if (button) button.disabled = false;
  if (loadedCount >= 1 && startButtons.every(button => !button.disabled || !characters[button.dataset.start])) {
    // Keep the other card disabled if its VRM failed, but do not hide the room.
    if (startButtons.some(button => !button.disabled)) els.loadStatus.textContent = 'комната дышит';
  }
  if (loadedCount >= 2) {
    els.loadBar.style.width = '100%';
    els.loadStatus.textContent = 'комната дышит';
  }
}

